function smooth(points:Point[]){return points.map((p,i,a)=>{if("'!i)return `M${p.x},${p.y}`;const prev=a[i-1];const before=a[i-2]||prev;const after=a[i+1]||p;return `C${prev.x+(p.x-before.x)/6},${prev.y+(p.y-before.y)/6} ${p.x-(after.x-prev.x)/6},${p.y-(after.y-prev.y)/6} ${p.x},${p.y}`}).join('"' ')}
export default function SalesEngine({series,formatX,formatY,unit}:ChartProps){
