 <defs><linearGradient id="sales-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#9984e9" stopOpacity=".14"/><stop offset="100%" stopColor="#9984e9" stopOpacity="0"/></linearGradient></defs>
 {[0,1,2,3,4].map(i=><g key={i}><line x1={L} x2={W-R} y1={sy(max*i/4)} y2={sy(max*i/4)} stroke="#ececf1" strokeDasharray={i?'"'3 5':undefined}/><text x={L-13} y={sy(max*i/4)+4} textAnchor=\"end\" fill=\"#91929e\" fontSize=\"11\">{i?"'`${Math.round(max*i/4/1000)} тыс.`:'"'0'}</text></g>)}
