 {series[0].data.filter((_,i,a)=>i%Math.ceil((a.length-1)/6)===0||i===a.length-1).map(p=><text key={p.x} x={sx(p.x)} y={H-9} textAnchor=\"middle\" fill=\"#91929e\" fontSize=\"11\">{formatX(p.x)}</text>)}
