 </section>
 <section className=\"bottom-grid\"><article className=\"sources-card\"><div className=\"section-top\"><div><h2>{mode==='sales'?'Продажи по источникам':'Состояние сервисов'}</h2><p>{mode==='sales'?'Откуда приходят ваши покупатели':'Доступность и производительность'}</p></div><button className=\"text-button\" onClick={()=>setModal('channels')}>Все источники<Icon name=\"chevron\" size={14}/></button></div>{mode==='sales'?<div className=\"table-wrap\"><table><thead><tr><th>ИСТОЧНИК</th><th>ВЫРУЧКА</th><th>ДИНАМИКА</th><th>ДОЛЯ</th></tr></thead><tbody>{channels.map(c=><tr key={c.name} className={channel===c.name?'row-selected':''} onClick={()=>setChannel(channel===c.name?'all':c.name)}><td><span className={"'`source-icon ${c.color}`}><Icon name={c.icon} size={18}/></span><span><strong>{c.name}</strong><small>{c.sub}</small></span></td><td>{money(c.revenue*period/30*(workspace==='"'Acme Store'?1:.64))} ₽</td><td><span className=\"table-growth\">↗ +{c.change.toString().replace('.',',')}%</span></td><td><div className=\"share\"><span className=\"share-track\"><span style={{width:"'`${c.share}%`}}/></span>{c.share}%</div></td></tr>)}</tbody></table></div>:<div className="service-list">{[{name:'"'API Gateway',latency:'84 мс'},{name:'База данных',latency:'12 мс'},{name:'Платёжный сервис',latency:'112 мс'}].map(s=><div key={s.name}><span className=\"source-icon purple\"><Icon name=\"layers\" size={18}/></span><strong>{s.name}</strong><span>{s.latency}</span><span className=\"healthy\"><span className=\"live-dot\"/>Работает</span></div>)}</div>}</article>
